function RaceJcpSubsystem:initialize(...)
    NetResponseEventManager:Get():AddListener(MsgID.JCP_INFO_S2C_RET, self, self.RecvMsg_RaceJCPInfo)
    NetResponseEventManager:Get():AddListener(MsgID.JCP_JOIN_S2C_RET, self, self.RecvMsg_RaceJCPJoin)
    NetResponseEventManager:Get():AddListener(MsgID.JCP_MATCH_S2C_RET, self, self.RecvMsg_RaceJCPMatch)
    NetResponseEventManager:Get():AddListener(MsgID.JCP_MATCH_END_S2C_RET, self, self.RecvMsg_RaceJCPMatchEnd)
    NetResponseEventManager:Get():AddListener(MsgID.JCP_CANCEL_S2C_RET, self, self.RecvMsg_RaceJCPCancel)
    NetResponseEventManager:Get():AddListener(MsgID.JCP_ACCEPT_S2C_RET, self, self.RecvMsg_RaceJCPAccept)
    NetResponseEventManager:Get():AddListener(MsgID.JCP_FINISH_S2C_RET, self, self.RecvMsg_RaceJCPFinish)
    NetResponseEventManager:Get():AddListener(MsgID.JCP_TEST_FINISH_S2C_RET, self, self.RecvMsg_RaceJCPTestFinish)
    NetResponseEventManager:Get():AddListener(MsgID.JCP_START_S2C_RET, self, self.RecvMsg_RaceJCPStart)
    NetResponseEventManager:Get():AddListener(MsgID.JCP_REPLAY_S2C_RET, self, self.RecvMsg_RaceJCPReplay)

end
local GetRaceJcpCallBack=nil
function RaceJcpSubsystem:SendMsg_RaceJCPInfo(backfunc)
    local data=CommonHelper:GetNetSendData({PlayerDataManager:Get():GetPlayerRID()})
    NetManager:Get():Send(MsgID.JCP_INFO_C2S_REQ,data)
    --UINotify:Get():SendNotification(UINotifyEvent.RaceJCPView_SetData)
end

function RaceJcpSubsystem:RecvMsg_RaceJCPInfo(data)
    ---@type SC_RetJcup
    local msg = assert(Dll_PB.decode("RetJcup", data))
    --log(" 返回JCP信息  ",ProtoMsgHelp.block(msg))
    if msg then
        RaceJcpManager:Get().JcpData:SetData(msg)
       if RaceJcpManager:Get():GetCurState()==RaceJCPType.None then
             CommonTipsHelper:Get():ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.JCPUnOpen))
        --elseif RaceJcpManager:Get():GetCurState()==RaceJCPType.RaceOver  then
        --    CommonTipsHelper:Get():ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.JCPUnOpen))
        else
            UIManager:Get():OpenView("RaceJCPView", CanvasType.MainCanvas, "RaceJCPView")
            UINotify:Get():SendNotification(UINotifyEvent.RaceJCPView_SetData)
        end
    end
    if GetRaceJcpCallBack then
        GetRaceJcpCallBack()
        GetRaceJcpCallBack=nil
    end
end

