function RaceJcpSubsystem:RecvMsg_RaceJCPStart(data)
    ---@type SC_RetStarts
    local msg = assert(Dll_PB.decode("RetStarts", data))
    --log(ProtoMsgHelp.block(msg))
    --RaceJcpManager:Get():SetRaceType(RaceJcpRaceType.Battle)
    --RaceJcpManager:Get():BeginBattle(msg)
    cs_coroutine.start(function()
        if UIManager:Get():IsPersistentViewShow("RaceJCPMatchingView") then
            UIManager:Get():HidePersistentView("RaceJCPMatchingView")
        end
        coroutine.yield(CS.UnityEngine.WaitForSeconds(0.2))
        RaceJcpManager:Get():SetRaceType(RaceJcpRaceType.Battle)
        RaceJcpManager:Get():BeginBattle(msg)
    end)
end

function RaceJcpSubsystem:SendMsg_RaceJCPReplay(rid,jcpId)
    local data = CommonHelper:GetNetSendData({PlayerDataManager:Get():GetPlayerRID(),rid,jcpId})
    NetManager:Get():Send(MsgID.JCP_REPLAY_C2S_REQ,data)
end

function RaceJcpSubsystem:RecvMsg_RaceJCPReplay(data)
    ---@type SC_RetRaceRecord
    local msg = assert(Dll_PB.decode("RetRaceRecord", data))
    --log(ProtoMsgHelp.block(msg))
    UIManager:Get():ClosePopup()
    RankListTestVerifyDataManager:Get():SetLookVersion(msg.starts.ver)
    cs_coroutine.start(function()
        coroutine.yield()
        RaceJcpManager:Get():SetRaceType(RaceJcpRaceType.Record)
        RaceJcpManager:Get():SetLookId(msg.lookrid)
        RaceJcpManager:Get():BeginBattle(msg.starts,false)
    end)
end

